WITH supplier_totals AS (SELECT supplier_id, SUM(CASE WHEN brand = 'Acme' THEN price ELSE 0 END) AS acme_price, SUM(CASE WHEN category = 'Electronics' THEN 1 ELSE 0 END) AS electronics_count FROM products GROUP BY supplier_id) SELECT suppliers.city, suppliers.supplier_name, supplier_totals.acme_price, supplier_totals.electronics_count FROM suppliers LEFT JOIN supplier_totals ON suppliers.id = supplier_totals.supplier_id WHERE supplier_totals.acme_price > 71 ORDER BY supplier_totals.acme_price
